//! Model Context Protocol server (JSON-RPC 2.0). [`Session`] holds the tools;
//! [`serve`] runs it over stdio (one message per line) and `http` serves the
//! same session over Streamable HTTP.
//!
//! The data tools are read-only: fixed query shapes over the index, with no
//! SQL passthrough and no file access. Writes exist only for the opt-in
//! memory store (`--memory`), whose own file is the only thing they touch.
//! stdout carries protocol messages only; diagnostics go to stderr.

use std::io::{self, BufRead, Write};
use std::path::PathBuf;

use anyhow::{Result, bail};
use serde_json::{Value, json};

use crate::card::CardOptions;
use crate::config::plural;
use crate::memory::{Forget, Kind, Memory, RecallRequest, Remember, Settings};
use crate::query::{AggregateRequest, Metric, Scope, SearchRequest, Sort, Store};
use crate::render;

pub const PROTOCOL_VERSIONS: &[&str] = &["2025-11-25", "2025-06-18", "2025-03-26", "2024-11-05"];

const DATA_INSTRUCTIONS: &str = "Leviathan searches a large indexed dataset and returns a few ranked, cited records instead of raw data. \
Call `describe` once to learn the fields, groups and filter values. Then use `search`: words for ranked matches, \
`group` to scope to one entity, `where` for exact filters, `since`/`until` for dates, no words for newest first. \
If a group is ambiguous, show the candidates and ask; never guess. Results marked OTHER come from a different group: say so. \
Use `get` only when the full record is needed.";

const MEMORY_INSTRUCTIONS: &str = "Leviathan memory: call `recall` with no arguments once at the start of a session, and with \
words or a `subject` before acting on anything you may have learned before. `remember` durable facts, preferences, \
decisions (with the reason) and lessons, one claim each; give anything that can change a `key` and a `subject` so the \
next write replaces it. Never store secrets, credentials or transient state. Superseded memories are history, not truth.";

const RECALL_ONLY_INSTRUCTIONS: &str = "Leviathan memory (read-only here): call `recall` with no arguments once at the start \
of a session, and with words or a `subject` before acting on anything you may have learned before.";

/// Which memory tools a client gets.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, clap::ValueEnum)]
pub enum MemoryTools {
    /// remember, recall, forget, memory_describe.
    #[default]
    All,
    /// recall and memory_describe only.
    Recall,
}

#[derive(Debug, Clone)]
pub struct MemoryOptions {
    pub path: PathBuf,
    pub settings: Settings,
    pub tools: MemoryTools,
}

#[derive(Debug, Clone)]
pub struct ServerOptions {
    pub index: PathBuf,
    pub card: CardOptions,
    pub memory: Option<MemoryOptions>,
}

/// One line summarizing the open index, appended to tool descriptions so the
/// agent knows the data's shape before its first call.
fn dataset_summary(store: &Store) -> Option<String> {
    let d = store.describe(5).ok()?;
    let (record, group) = (&d.about.record, &d.about.group);
    let mut s = format!(
        "This index: {}{} {}",
        d.about.name.as_deref().map(|n| format!("{n}, ")).unwrap_or_default(),
        render::thousands(d.record_count),
        plural(record)
    );
    if !d.kinds.is_empty() {
        let kinds: Vec<String> = d
            .kinds
            .iter()
            .map(|k| {
                let group = k.fields.group.as_deref().map(|g| format!(", group = {g}")).unwrap_or_default();
                format!("{} ({} {}{group})", k.name, render::thousands(k.records), plural(&k.record))
            })
            .collect();
        s.push_str(&format!(
            " of {} kinds: {}. Ids are `<kind>:<id>`; `where _kind=<kind>` keeps one kind, `by: _kind` counts per kind",
            d.kinds.len(),
            kinds.join(", ")
        ));
    }
    if let Some(g) = &d.fields.group {
        s.push_str(&format!(" across {} {} (group = {g})", render::thousands(d.group_count), plural(group)));
    }
    if let (Some(a), Some(b)) = (&d.date_min, &d.date_max) {
        s.push_str(&format!(", dated {} to {}", render::day(a), render::day(b)));
    }
    if !d.filters.is_empty() {
        let parts: Vec<String> = d
            .filters
            .iter()
            .map(|f| {
                let vals: Vec<&str> = f.top.iter().take(4).map(|(v, _)| v.as_str()).collect();
                let more = if f.distinct > vals.len() as i64 { ", ..." } else { "" };

content.content:
100	                let more = if f.distinct > vals.len() as i64 { ", ..." } else { "" };
101	                format!("{} ({}{more})", f.field, vals.join(", "))
102	            })
103	            .collect();
104	        s.push_str(&format!(". Filters: {}", parts.join("; ")));
105	    }
106	    s.push('.');
107	    Some(s)
108	}
109	
110	fn format_param() -> Value {
111	    json!({"type": "string", "enum": ["text", "json"], "description": "text (default, fewest tokens) or json"})
112	}
113	
114	fn data_tools(store: Option<&Store>) -> Vec<Value> {
115	    let format = format_param();
116	    let mut search_desc = "Ranked records for free-text words (quote \"exact phrases\", -exclude words), optionally scoped \
117	        to one group, filtered by exact field values and a date range. With no words, lists newest first. Resolves the group \
118	        itself and returns candidates instead of guessing when it is ambiguous."
119	        .to_string();
120	    if let Some(summary) = store.and_then(dataset_summary) {
121	        search_desc = format!("{search_desc} {summary}");
122	    }
123	    vec![
124	        json!({
125	            "name": "search",
126	            "description": search_desc,
127	            "inputSchema": {
128	                "type": "object",
129	                "properties": {
130	                    "query": {"type": "string", "description": "Words to rank by. Omit to list newest first."},
131	                    "group": {"type": "string", "description": "Group key or name, as the user said it"},
132	                    "scope": {"type": "string", "enum": ["group", "others", "all"], "description": "With a group: group (default), others = every other group"},
133	                    "where": {"type": "object", "additionalProperties": {"anyOf": [{"type": "string"}, {"type": "array", "items": {"type": "string"}}]}, "description": "Exact filters, e.g. {\"status\": \"open\"}; an array means any of"},
134	                    "where_list": {"type": "array", "items": {"type": "string"}, "description": "Same filters as field=value strings, e.g. [\"status=open\"]"},
135	                    "since": {"type": "string", "description": "YYYY, YYYY-MM or YYYY-MM-DD"},
136	                    "until": {"type": "string", "description": "Inclusive, same formats"},
137	                    "sort": {"type": "string", "enum": ["relevance", "newest"]},
138	                    "limit": {"type": "integer", "minimum": 1, "maximum": 25, "description": "Default 5"},
139	                    "offset": {"type": "integer", "minimum": 0},
140	                    "format": format
141	                }
142	            },
143	            "annotations": {"readOnlyHint": true, "openWorldHint": false}
144	        }),
145	        json!({
146	            "name": "resolve_group",
147	            "description": "Group key or name to candidate groups (key, name, record count, how it matched).",
148	            "inputSchema": {
149	                "type": "object",
150	                "properties": {"query": {"type": "string"}, "limit": {"type": "integer", "minimum": 1, "maximum": 25}, "format": format},
151	                "required": ["query"]
152	            },
153	            "annotations": {"readOnlyHint": true, "openWorldHint": false}
154	        }),
155	        json!({
156	            "name": "get",
157	            "description": "One complete record by id, exactly as ingested.",
158	            "inputSchema": {"type": "object", "properties": {"id": {"type": "string"}}, "required": ["id"]},
159	            "annotations": {"readOnlyHint": true, "openWorldHint": false}
160	        }),
161	        json!({
162	            "name": "describe",
163	            "description": "The dataset's fields, groups, filter values with counts, date range and example calls.",
164	            "inputSchema": {"type": "object", "properties": {"format": format}},
165	            "annotations": {"readOnlyHint": true, "openWorldHint": false}
166	        }),
167	        json!({
168	            "name": "aggregate",
169	            "description": "Exact counts and totals over every matching record, from the index: how many, how many different, \
170	                which group has the most, per year or month, per any field, or two at once (group,month). Count records, \
171	                count distinct values of a field, or sum/avg/min/max a numeric field; keep only records meeting numeric \
172	                conditions (hours>4). Takes the same group, filters, words and dates as search. Use it instead of reading \
173	                or scanning the data for any question about how many, how much, or which most.",
174	            "inputSchema": {
175	                "type": "object",
176	                "properties": {
177	                    "by": {"type": "string", "description": "group, year, month, day, a filter field or any field (parts[].name); two comma-separated for a breakdown (group,month); omit for one total"},
178	                    "metric": {"type": "string", "enum": ["count", "distinct", "sum", "avg", "min", "max"], "description": "Default count; distinct counts different values of field"},
179	                    "field": {"type": "string", "description": "Field for distinct (any values) or sum/avg/min/max (numbers), e.g. labor[].tech or hours"},
180	                    "numeric": {"type": "array", "items": {"type": "string"}, "description": "Keep records whose number field compares: hours>4, total<=100 (> >= < <= = !=)"},
181	                    "group": {"type": "string", "description": "One group key or name"},
182	                    "group_contains": {"type": "string", "description": "Every group whose key or name contains this, e.g. a site or prefix"},
183	                    "where": {"type": "object", "additionalProperties": {"anyOf": [{"type": "string"}, {"type": "array", "items": {"type": "string"}}]}, "description": "Exact filters, as in search"},
184	                    "query": {"type": "string", "description": "Words the records must match (optional)"},
185	                    "since": {"type": "string", "description": "YYYY, YYYY-MM or YYYY-MM-DD"},
186	                    "until": {"type": "string", "description": "Inclusive, same formats"},
187	                    "limit": {"type": "integer", "minimum": 1, "maximum": 200, "description": "Rows to return, largest first; default 20"},
188	                    "format": format
189	                }
190	            },
191	            "annotations": {"readOnlyHint": true, "openWorldHint": false}
192	        }),
193	    ]
194	}
195	
196	/// Memory tool schemas are flat (no anyOf, no free-form objects) so every
197	/// client's schema dialect accepts them, Gemini and OpenAI strict included.
198	/// Memory tools. Schemas list what agents use; `limit`, `until` and
199	/// `format` are accepted without being advertised, to keep every session
200	/// cheap.
201	fn memory_tools(tools: MemoryTools, namespace: &str, data: bool) -> Vec<Value> {
202	    let kinds: Vec<&str> = Kind::ALL.iter().map(|k| k.as_str()).collect();
203	    let mut recall_props = json!({
204	        "query": {"type": "string", "description": "Words to rank by; omit for the briefing"},
205	        "subject": {"type": "string", "description": "Only about this person, project or thing"},
206	        "kind": {"type": "string", "description": format!("Comma list: {}", Kind::NAMES)},
207	        "ns": {"type": "string", "description": "Namespaces, comma list, or *"},
208	        "since": {"type": "string", "description": "YYYY, YYYY-MM or YYYY-MM-DD"},
209	        "as_of": {"type": "string", "description": "What was true at the end of this date"},
210	        "history": {"type": "boolean", "description": "Include replaced and forgotten memories"},
211	        "budget": {"type": "integer", "description": "Tokens; default 800"}
212	    });
213	    if data {
214	        recall_props["with_records"] =
215	            json!({"type": "boolean", "description": "Add the indexed records memories reference"});
216	    }
217	    let mut out = vec![json!({
218	        "name": "recall",
219	        "description": "Current memories ranked by relevance, recency and importance, within a token budget. No arguments at \
220	            session start; words or a subject before acting on anything you may know.",
221	        "inputSchema": {"type": "object", "properties": recall_props},
222	        "annotations": {"readOnlyHint": true, "openWorldHint": false}
223	    })];
224	    if tools == MemoryTools::All {
225	        let mut props = json!({
226	            "text": {"type": "string", "description": "One claim, in a sentence"},
227	            "kind": {"type": "string", "enum": kinds},
228	            "subject": {"type": "string", "description": "Who or what it is about"},
229	            "key": {"type": "string", "description": "The slot that can change: editor, deploy.target, owner"},
230	            "importance": {"type": "integer", "minimum": 1, "maximum": 5, "description": "Default 3"},
231	            "tags": {"type": "array", "items": {"type": "string"}},
232	            "source": {"type": "string", "description": "user, observed, a document"},
233	            "pinned": {"type": "boolean", "description": "Lead every briefing"},
234	            "expires": {"type": "string", "description": "A date, or 12h, 30d, 6w"},
235	            "aliases": {"type": "array", "items": {"type": "string"}, "description": "Other names for the subject"},
236	            "ns": {"type": "string", "description": format!("Default {namespace}")}
237	        });
238	        if data {
239	            props["refs"] =
240	                json!({"type": "array", "items": {"type": "string"}, "description": "Related record ids"});
241	        }
242	        out.push(json!({
243	            "name": "remember",
244	            "description": "Store one durable fact, preference, decision (with why), lesson, event or task. Give anything that \
245	                can change a subject and key, so the next write replaces it. Restatements merge; secrets are refused.",
246	            "inputSchema": {"type": "object", "properties": props, "required": ["text"]},
247	            "annotations": {"readOnlyHint": false, "destructiveHint": false, "idempotentHint": true, "openWorldHint": false}
248	        }));
249	        out.push(json!({
250	            "name": "forget",
251	            "description": "Mark a memory no longer true (kept in history): its id, or a subject and key.",
252	            "inputSchema": {
253	                "type": "object",
254	                "properties": {
255	                    "id": {"type": "string"},
256	                    "subject": {"type": "string"},
257	                    "key": {"type": "string"},
258	                    "ns": {"type": "string"},
259	                    "reason": {"type": "string"}
260	                }
261	            },
262	            "annotations": {"readOnlyHint": false, "destructiveHint": true, "idempotentHint": true, "openWorldHint": false}
263	        }));
264	    }
265	    out.push(json!({
266	        "name": "memory_describe",
267	        "description": "Memory counts by kind, namespace and subject.",
268	        "inputSchema": {"type": "object", "properties": {}},
269	        "annotations": {"readOnlyHint": true, "openWorldHint": false}
270	    }));
271	    out
272	}
273	
274	/// Tool list for a server with or without data and memory. Used by `wrap`
275	/// (to estimate schema cost) and the function-calling exports.
276	pub fn tool_definitions(store: Option<&Store>, memory: Option<(MemoryTools, &str)>, data: bool) -> Value {
277	    let mut tools = if data { data_tools(store) } else { Vec::new() };
278	    if let Some((which, ns)) = memory {
279	        tools.extend(memory_tools(which, ns, data));
280	    }
281	    Value::Array(tools)
282	}
283	
284	/// Tool state for one client connection.
285	pub struct Session {
286	    opts: ServerOptions,
287	    store: Option<Store>,
288	    memory: Option<Memory>,
289	}
290	
291	fn text_arg(args: &Value, k: &str) -> Option<String> {
292	    args.get(k).and_then(Value::as_str).map(str::trim).filter(|s| !s.is_empty()).map(str::to_string)
293	}
294	
295	fn int_arg(args: &Value, k: &str) -> Option<usize> {
296	    args.get(k)
297	        .and_then(|v| v.as_u64().or_else(|| v.as_str().and_then(|s| s.trim().parse().ok())))
298	        .map(|v| v as usize)
299	}
300	
301	fn bool_arg(args: &Value, k: &str) -> bool {
302	    match args.get(k) {
303	        Some(Value::Bool(b)) => *b,
304	        Some(Value::String(s)) => matches!(s.trim(), "true" | "1" | "yes"),
305	        _ => false,
306	    }
307	}
308	
309	/// `where` (an object of field to value or values) and `where_list`
310	/// (`field=value` strings) as filter pairs.
311	fn where_filters(args: &Value) -> Result<Vec<(String, String)>> {
312	    let mut filters = Vec::new();
313	    if let Some(Value::Object(map)) = args.get("where") {
314	        for (field, v) in map {
315	            match v {
316	                Value::Array(items) => {
317	                    filters.extend(items.iter().filter_map(scalar).map(|s| (field.clone(), s)))
318	                }
319	                other => filters.extend(scalar(other).map(|s| (field.clone(), s))),
320	            }
321	        }
322	    }
323	    for f in list_arg(args, "where_list") {
324	        match f.split_once('=') {
325	            Some((k, v)) if !k.trim().is_empty() => filters.push((k.trim().into(), v.trim().into())),
326	            _ => bail!("where_list items look like field=value, got {f:?}"),
327	        }
328	    }
329	    Ok(filters)
330	}
331	
332	/// An array of strings, or one comma-separated string.
333	fn list_arg(args: &Value, k: &str) -> Vec<String> {
334	    match args.get(k) {
335	        Some(Value::Array(items)) => {
336	            items.iter().filter_map(scalar).filter(|s| !s.trim().is_empty()).collect()
337	        }
338	        Some(Value::String(s)) => {
339	            s.split(',').map(str::trim).filter(|s| !s.is_empty()).map(str::to_string).collect()
340	        }
341	        _ => Vec::new(),
342	    }
343	}
344	
345	fn kinds_arg(args: &Value) -> Result<Vec<Kind>> {
346	    list_arg(args, "kind")
347	        .iter()
348	        .map(|k| Kind::parse(k).ok_or_else(|| anyhow::anyhow!("unknown kind {k:?}; use {}", Kind::NAMES)))
349	        .collect()
350	}
351	
352	impl Session {
353	    pub fn new(opts: ServerOptions) -> Self {
354	        Self { opts, store: None, memory: None }
355	    }
356	
357	    /// Data tools are offered unless this is a memory server without an index.
358	    pub fn data_enabled(&self) -> bool {
359	        self.opts.memory.is_none() || self.opts.index.exists()
360	    }
361	
362	    pub fn memory_tools(&self) -> Option<MemoryTools> {
363	        self.opts.memory.as_ref().map(|m| m.tools)
364	    }
365	
366	    fn ensure_store(&mut self) -> Result<()> {
367	        match &mut self.store {
368	            Some(store) => {
369	                store.reload_if_replaced()?;
370	            }
371	            None => self.store = Some(Store::open(&self.opts.index, self.opts.card)?),
372	        }
373	        Ok(())
374	    }
375	
376	    fn store(&mut self) -> Result<&Store> {
377	        self.ensure_store()?;
378	        Ok(self.store.as_ref().expect("store opened above"))
379	    }
380	
381	    fn ensure_memory(&mut self) -> Result<()> {
382	        if self.memory.is_none() {
383	            let Some(m) = &self.opts.memory else {
384	                bail!("memory is not enabled on this server (start it with --memory)")
385	            };
386	            self.memory = Some(Memory::open(&m.path, m.settings.clone())?);
387	        }
388	        Ok(())
389	    }
390	
391	    /// Open both stores now so startup problems show up in the log.
392	    pub fn warm_up(&mut self) -> Vec<String> {
393	        let mut lines = Vec::new();
394	        if self.data_enabled() {
